// BLUEPRINT §6: iPhone-only on every target. Extension targets generated by
// @bacons/apple-targets default to "1,2" (iPhone + iPad); this pins all
// build configurations in the final project file to 1.
const { withDangerousMod } = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

module.exports = function withIphoneOnly(config) {
  return withDangerousMod(config, [
    'ios',
    async (cfg) => {
      // Runs after the project is written; patch the file on disk.
      const iosDir = cfg.modRequest.platformProjectRoot;
      const proj = fs.readdirSync(iosDir).find((f) => f.endsWith('.xcodeproj'));
      if (!proj) return cfg;
      const file = path.join(iosDir, proj, 'project.pbxproj');
      const patch = () => {
        const src = fs.readFileSync(file, 'utf8');
        const out = src.replace(/TARGETED_DEVICE_FAMILY = "1,2";/g, 'TARGETED_DEVICE_FAMILY = 1;');
        if (out !== src) fs.writeFileSync(file, out);
      };
      patch();
      // apple-targets writes its targets late in the mod chain; patch again
      // once the event loop settles after prebuild finishes writing.
      process.once('beforeExit', patch);
      return cfg;
    },
  ]);
};
